const EventEmitter = require('events');

const serverEmitter = new EventEmitter();

// 1. Listen forever
serverEmitter.on('request', (url) => {
  console.log(`[LOGGER]: New request to ${url}`);
});

// 2. Listen only ONCE
serverEmitter.once('request', () => {
  console.log(`[METRICS]: Server received its very first request!`);
});

// 3. Triggering the events
console.log("--- First Request ---");
serverEmitter.emit('request', '/home'); 
// Logs BOTH the logger and the metric.

console.log("\n--- Second Request ---");
serverEmitter.emit('request', '/about'); 
// Logs ONLY the logger! The .once() listener is gone.
